        [[nodiscard]] std::uint64_t CurrentThreadCpu100ns() noexcept
        {
            FILETIME creation{}, exit{}, kernel{}, user{};
            if (!GetThreadTimes(GetCurrentThread(), &creation, &exit, &kernel, &user))
            {
                return 0;
            }
            ULARGE_INTEGER kernelValue{};
            kernelValue.LowPart = kernel.dwLowDateTime;
            kernelValue.HighPart = kernel.dwHighDateTime;
            ULARGE_INTEGER userValue{};
            userValue.LowPart = user.dwLowDateTime;
            userValue.HighPart = user.dwHighDateTime;
            return kernelValue.QuadPart + userValue.QuadPart;
        }

        [[nodiscard]] std::uint64_t CurrentProcessReadBytes() noexcept
        {
            IO_COUNTERS counters{};
            return GetProcessIoCounters(GetCurrentProcess(), &counters)
                ? counters.ReadTransferCount
                : 0ULL;
        }

        template <typename Callback>
        class ScopeExit final
        {
        public:
            explicit ScopeExit(Callback callback) : callback_(std::move(callback)) {}
            ~ScopeExit() { callback_(); }
            ScopeExit(const ScopeExit&) = delete;
            ScopeExit& operator=(const ScopeExit&) = delete;
        private:
            Callback callback_;
        };

        std::filesystem::path BuildSessionLogPath(const std::filesystem::path& root)
        {
            const auto now = std::chrono::system_clock::now();
            const auto value = std::chrono::system_clock::to_time_t(now);
            std::tm local{};
            localtime_s(&local, &value);
            std::wstringstream name;
            name << L"PhoenixClient_" << std::put_time(&local, L"%Y%m%d-%H%M%S")
                 << L"_pid" << GetCurrentProcessId() << L".log";
            return root / name.str();
        }

