        std::wstring ChatTextToWide(const std::string& text)
        {
            if (text.empty()) return {};
            auto codePage = CP_UTF8;
            auto count = MultiByteToWideChar(codePage, MB_ERR_INVALID_CHARS, text.data(), static_cast<int>(text.size()), nullptr, 0);
            if (count <= 0)
            {
                codePage = CP_ACP;
                count = MultiByteToWideChar(codePage, 0, text.data(), static_cast<int>(text.size()), nullptr, 0);
            }
            if (count <= 0) return {};
            std::wstring result(static_cast<std::size_t>(count), L'\0');
            (void)MultiByteToWideChar(codePage, codePage == CP_UTF8 ? MB_ERR_INVALID_CHARS : 0,
                text.data(), static_cast<int>(text.size()), result.data(), count);
            return result;
        }

        std::string ChatTextToUtf8(const std::wstring_view text)
        {
            if (text.empty()) return {};
            const auto count = WideCharToMultiByte(
                CP_UTF8, WC_ERR_INVALID_CHARS, text.data(), static_cast<int>(text.size()),
                nullptr, 0, nullptr, nullptr);
            if (count <= 0) return {};
            std::string result(static_cast<std::size_t>(count), '\0');
            (void)WideCharToMultiByte(
                CP_UTF8, WC_ERR_INVALID_CHARS, text.data(), static_cast<int>(text.size()),
                result.data(), count, nullptr, nullptr);
            return result;
        }

