        constexpr std::uint32_t ColorRefToRgba(const std::uint32_t color) noexcept
        {
            return (color & 0x000000FFU) << 24U |
                (color & 0x0000FF00U) << 8U |
                (color & 0x00FF0000U) >> 8U |
                0x000000FFU;
        }

