        graphics::ImageData RasterizeAsciiText(
            const std::string& text,
            const std::uint32_t width,
            const std::uint32_t height,
            const std::uint32_t color,
            const std::uint8_t textAlpha)
        {
            graphics::ImageData image;
            image.width = std::max(1U, width);
            image.height = std::max(1U, height);
            image.format = graphics::PixelFormat::Rgba8;
            image.pixels.assign(static_cast<std::size_t>(image.width) * image.height * 4U, 0U);
            if (text.empty())
            {
                return image;
            }

            BITMAPINFO info{};
            info.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
            info.bmiHeader.biWidth = static_cast<LONG>(image.width);
            info.bmiHeader.biHeight = -static_cast<LONG>(image.height);
            info.bmiHeader.biPlanes = 1;
            info.bmiHeader.biBitCount = 32;
            info.bmiHeader.biCompression = BI_RGB;

            void* bits = nullptr;
            HDC screen = GetDC(nullptr);
            HDC dc = CreateCompatibleDC(screen);
            HBITMAP bitmap = CreateDIBSection(screen, &info, DIB_RGB_COLORS, &bits, nullptr, 0);
            ReleaseDC(nullptr, screen);
            if (dc == nullptr || bitmap == nullptr || bits == nullptr)
            {
                if (bitmap != nullptr)
                {
                    DeleteObject(bitmap);
                }
                if (dc != nullptr)
                {
                    DeleteDC(dc);
                }
                return image;
            }

            auto* pixels = static_cast<std::uint32_t*>(bits);
            std::fill(pixels, pixels + static_cast<std::size_t>(image.width) * image.height, 0U);
            const auto oldBitmap = SelectObject(dc, bitmap);
            const auto textPaddingX = static_cast<int>(std::clamp<std::uint32_t>(image.width / 32U, 2U, 4U));
            auto fontPixels = static_cast<int>(std::clamp<std::uint32_t>(image.height > 5U ? image.height - 5U : image.height, 8U, 14U));
            HFONT font = nullptr;
            SIZE textSize{};
            while (fontPixels >= 8)
            {
                if (font != nullptr)
                {
                    DeleteObject(font);
                }
                font = CreateFontW(
                    -fontPixels,
                    0,
                    0,
                    0,
                    FW_NORMAL,
                    FALSE,
                    FALSE,
                    FALSE,
                    DEFAULT_CHARSET,
                    OUT_DEFAULT_PRECIS,
                    CLIP_DEFAULT_PRECIS,
                    CLEARTYPE_QUALITY,
                    DEFAULT_PITCH | FF_DONTCARE,
                    L"Segoe UI");
                const auto wideText = ChatTextToWide(text);
                const auto measureOldFont = SelectObject(dc, font);
                (void)GetTextExtentPoint32W(dc, wideText.c_str(), static_cast<int>(wideText.size()), &textSize);
                SelectObject(dc, measureOldFont);
                if (textSize.cx <= static_cast<LONG>(std::max<int>(1, static_cast<int>(image.width) - (textPaddingX * 2))) &&
                    textSize.cy <= static_cast<LONG>(std::max<int>(1, static_cast<int>(image.height))))
                {
                    break;
                }
                --fontPixels;
            }
            const auto oldFont = SelectObject(dc, font);
            SetBkMode(dc, TRANSPARENT);
            SetTextColor(dc, color);
            const auto textY = std::max<int>(0, (static_cast<int>(image.height) - static_cast<int>(std::max<LONG>(1, textSize.cy))) / 2);
            const auto wideText = ChatTextToWide(text);
            TextOutW(dc, textPaddingX, textY, wideText.c_str(), static_cast<int>(wideText.size()));
            GdiFlush();

            for (std::uint32_t y = 0; y < image.height; ++y)
            {
                for (std::uint32_t x = 0; x < image.width; ++x)
                {
                    const auto src = pixels[static_cast<std::size_t>(y) * image.width + x];
                    const auto b = static_cast<std::uint8_t>(src & 0xFFU);
                    const auto g = static_cast<std::uint8_t>((src >> 8U) & 0xFFU);
                    const auto r = static_cast<std::uint8_t>((src >> 16U) & 0xFFU);
                    const auto sampled = std::max({ r, g, b });
                    const auto colorPeak = std::max({
                        static_cast<std::uint8_t>(GetRValue(color)),
                        static_cast<std::uint8_t>(GetGValue(color)),
                        static_cast<std::uint8_t>(GetBValue(color)) });
                    const auto glyphAlpha = colorPeak == 0U
                        ? sampled
                        : static_cast<std::uint8_t>(std::min<std::uint32_t>(
                            255U,
                            (static_cast<std::uint32_t>(sampled) * 255U) / colorPeak));
                    const auto dst = (static_cast<std::size_t>(y) * image.width + x) * 4U;
                    image.pixels[dst + 0U] = GetRValue(color);
                    image.pixels[dst + 1U] = GetGValue(color);
                    image.pixels[dst + 2U] = GetBValue(color);
                    image.pixels[dst + 3U] = static_cast<std::uint8_t>(
                        (static_cast<std::uint32_t>(glyphAlpha) * textAlpha) / 255U);
                }
            }

            SelectObject(dc, oldFont);
            SelectObject(dc, oldBitmap);
            DeleteObject(font);
            DeleteObject(bitmap);
            DeleteDC(dc);
            return image;
        }

