        std::string NarrowAscii(const std::wstring& value)
        {
            std::string result;
            result.reserve(value.size());
            for (const auto ch : value)
            {
                result.push_back(ch >= 0 && ch < 128 ? static_cast<char>(ch) : '?');
            }
            return result;
        }

