        std::uint16_t LegacyPaletteColorSet(const std::uint32_t selectedIndex, const bool skin) noexcept
        {
            const auto column = static_cast<std::size_t>(selectedIndex % 8U);
            const auto row = static_cast<std::size_t>((selectedIndex / 8U) % 3U);
            return skin ? kLegacySkinColorSets[column][row] : kLegacyHairColorSets[column][row];
        }

        assets::LegacyIndexedColorMapping LegacyColorMapping(std::initializer_list<std::pair<std::uint32_t, std::uint16_t>> values)
        {
            assets::LegacyIndexedColorMapping mapping;
            mapping.colorSetByIndex.fill(0);
            for (const auto& [slot, colorSet] : values)
            {
                if (slot < mapping.colorSetByIndex.size())
                {
                    mapping.colorSetByIndex[slot] = colorSet < 795U ? colorSet : 0U;
                }
            }
            return mapping;
        }

        std::uint32_t LegacyColorMappingHash(const assets::LegacyIndexedColorMapping& mapping) noexcept
        {
            std::uint32_t hash = 2166136261U;
            for (const auto value : mapping.colorSetByIndex)
            {
                hash ^= static_cast<std::uint8_t>(value & 0xFFU);
                hash *= 16777619U;
                hash ^= static_cast<std::uint8_t>((value >> 8U) & 0xFFU);
                hash *= 16777619U;
            }
            return hash;
        }

        std::uint64_t HashWideString(const std::wstring_view value) noexcept
        {
            std::uint64_t hash = 1469598103934665603ULL;
            for (const auto ch : value)
            {
                const auto code = static_cast<std::uint32_t>(ch);
                hash ^= static_cast<std::uint8_t>(code & 0xFFU);
                hash *= 1099511628211ULL;
                hash ^= static_cast<std::uint8_t>((code >> 8U) & 0xFFU);
                hash *= 1099511628211ULL;
            }
            return hash;
        }

        std::uint64_t LegacySplitSpriteCacheKey(
            const std::wstring_view packName,
            const std::wstring_view extension,
            const assets::LegacyAssetFormat format,
            const std::uint32_t spriteId,
            const assets::LegacyIndexedColorMapping& colorMapping) noexcept
        {
            auto key = HashWideString(packName);
            key ^= HashWideString(extension) + 0x9E3779B97F4A7C15ULL + (key << 6U) + (key >> 2U);
            key ^= static_cast<std::uint64_t>(format) + 0x9E3779B97F4A7C15ULL + (key << 6U) + (key >> 2U);
            key ^= static_cast<std::uint64_t>(spriteId) + 0x9E3779B97F4A7C15ULL + (key << 6U) + (key >> 2U);
            key ^= static_cast<std::uint64_t>(LegacyColorMappingHash(colorMapping)) + 0x9E3779B97F4A7C15ULL + (key << 6U) + (key >> 2U);
            return key;
        }

        enum class CreatureLegacyVisualKind : std::uint8_t
        {
            Generic,
            Slayer,
            Vampire,
            Ousters
        };

        [[nodiscard]] CreatureLegacyVisualKind ResolveLegacyCreatureVisualKind(
            const content::CreatureInfo* creature,
            const content::CreatureSpriteInfo* primarySprite) noexcept
        {
            if (creature != nullptr && !creature->spriteTypes.empty())
            {
                const auto firstSpriteType = creature->spriteTypes.front();
                if (firstSpriteType <= 1U)
                {
                    return CreatureLegacyVisualKind::Slayer;
                }
                if (firstSpriteType == 2U || firstSpriteType == 3U)
                {
                    return CreatureLegacyVisualKind::Vampire;
                }
                if ((creature->tribe == 4U || creature->tribe == 5U) &&
                    creature->creatureType != 717U &&
                    creature->creatureType != 721U &&
                    creature->creatureType != 723U)
                {
                    return CreatureLegacyVisualKind::Ousters;
                }
            }

            if (primarySprite != nullptr && (primarySprite->flags & content::CreatureSpritePlayer) != 0U)
            {
                if ((primarySprite->flags & content::CreatureSpriteSlayer) != 0U || primarySprite->spriteType <= 1U)
                {
                    return CreatureLegacyVisualKind::Slayer;
                }
                if ((primarySprite->flags & content::CreatureSpriteVampire) != 0U ||
                    primarySprite->spriteType == 2U ||
                    primarySprite->spriteType == 3U)
                {
                    return CreatureLegacyVisualKind::Vampire;
                }
                if ((primarySprite->flags & content::CreatureSpriteOusters) != 0U)
                {
                    return CreatureLegacyVisualKind::Ousters;
                }
            }

            return CreatureLegacyVisualKind::Generic;
        }

        template <typename TValue>
        void TrimMapCacheToBudget(std::map<std::uint64_t, TValue>& cache, const std::size_t maxEntries)
        {
            constexpr std::size_t kTrimBatch = 64U;
            std::size_t erased = 0U;
            while (cache.size() > maxEntries && erased < kTrimBatch)
            {
                cache.erase(cache.begin());
                ++erased;
            }
        }

        std::uint32_t SlayerClassIndex(const frontend::CreateClass selectedClass) noexcept
        {
            switch (selectedClass)
            {
            case frontend::CreateClass::Sword:
                return 1U;
            case frontend::CreateClass::Gun:
                return 2U;
            case frontend::CreateClass::Heal:
                return 3U;
            case frontend::CreateClass::Enchant:
                return 4U;
            case frontend::CreateClass::Blade:
            default:
                return 0U;
            }
        }

        std::string SlayerClassName(const frontend::CreateClass selectedClass)
        {
            constexpr std::array<std::string_view, 5> names{ "Blade", "Sword", "Gun", "Heal", "Enchant" };
            return std::string(names[SlayerClassIndex(selectedClass)]);
        }

        std::uint32_t CharacterCreatePreviewVisualKey(const frontend::CharacterCreateModel& model) noexcept
        {
            if (model.race == frontend::CreateRace::Slayer)
            {
                return model.gender == frontend::CreateGender::Female ? 1U : 0U;
            }

            if (model.race == frontend::CreateRace::Vampire)
            {
                return model.gender == frontend::CreateGender::Female ? 3U : 2U;
            }

            return 4U;
        }

        std::optional<graphics::ImageData> ReadIndexedSpriteFromSplitPackFromPaths(
            assets::SpriteArchiveReader& reader,
            const std::filesystem::path& packDirectory,
            const std::filesystem::path& index,
            const std::wstring_view cacheName,
            const std::wstring_view extension,
            const assets::LegacyAssetFormat format,
            const std::uint32_t spriteId,
            const assets::LegacyIndexedColorMapping& colorMapping,
            std::map<std::uint64_t, graphics::ImageData>& cache)
        {
            const auto cacheKey = LegacySplitSpriteCacheKey(cacheName, extension, format, spriteId, colorMapping);
            if (const auto cached = cache.find(cacheKey); cached != cache.end())
            {
                return cached->second;
            }

            const auto splitBase = FindSplitArchiveBase(packDirectory, extension, spriteId);
            const auto archive = SplitArchivePath(packDirectory, extension, splitBase);
            auto decoded = reader.ReadSplitIndexedSprite565(
                archive,
                index,
                static_cast<std::uint16_t>(spriteId),
                static_cast<std::uint16_t>(splitBase),
                format,
                &colorMapping);
            if (!decoded.value || decoded.value->image.Empty())
            {
                return std::nullopt;
            }

            auto [inserted, _] = cache.emplace(cacheKey, std::move(decoded.value->image));
            return inserted->second;
        }

        std::optional<graphics::ImageData> ReadIndexedSpriteFromSplitPack(
            assets::SpriteArchiveReader& reader,
            const std::filesystem::path& imageRoot,
            const std::wstring_view packName,
            const std::wstring_view extension,
            const assets::LegacyAssetFormat format,
            const std::uint32_t spriteId,
            const assets::LegacyIndexedColorMapping& colorMapping,
            std::map<std::uint64_t, graphics::ImageData>& cache)
        {
            const auto extensionString = std::wstring(extension);
            const auto packDirectory = imageRoot / (std::wstring(packName) + L"." + extensionString);
            const auto index = imageRoot / (std::wstring(packName) + L"." + extensionString + L"i");
            return ReadIndexedSpriteFromSplitPackFromPaths(
                reader,
                packDirectory,
                index,
                std::wstring(packName) + L"." + extensionString,
                extension,
                format,
                spriteId,
                colorMapping,
                cache);
        }

        void BlitImage(graphics::ImageData& target, const graphics::ImageData& source, const std::int32_t x, const std::int32_t y)
        {
            if (target.Empty() || source.Empty())
            {
                return;
            }

            for (std::uint32_t srcY = 0; srcY < source.height; ++srcY)
            {
                const auto dstY = y + static_cast<std::int32_t>(srcY);
                if (dstY < 0 || dstY >= static_cast<std::int32_t>(target.height))
                {
                    continue;
                }

                for (std::uint32_t srcX = 0; srcX < source.width; ++srcX)
                {
                    const auto dstX = x + static_cast<std::int32_t>(srcX);
                    if (dstX < 0 || dstX >= static_cast<std::int32_t>(target.width))
                    {
                        continue;
                    }

                    const auto srcOffset = (static_cast<std::size_t>(srcY) * source.width + srcX) * 4U;
                    const auto alpha = source.pixels[srcOffset + 3U];
                    if (alpha == 0U)
                    {
                        continue;
                    }

                    const auto dstOffset = (static_cast<std::size_t>(dstY) * target.width + static_cast<std::uint32_t>(dstX)) * 4U;
                    target.pixels[dstOffset + 0U] = source.pixels[srcOffset + 0U];
                    target.pixels[dstOffset + 1U] = source.pixels[srcOffset + 1U];
                    target.pixels[dstOffset + 2U] = source.pixels[srcOffset + 2U];
                    target.pixels[dstOffset + 3U] = alpha;
                }
            }
        }

        struct ComposedFramePackImage
        {
            graphics::ImageData image;
            std::int32_t originX{ 0 };
            std::int32_t originY{ 0 };
        };

        std::int32_t DivideLegacyShadowOrigin(const std::int32_t value, const std::uint32_t shift) noexcept
        {
            if (shift == 0U)
            {
                return value;
            }

            const auto divisor = static_cast<std::int32_t>(1U << shift);
            if (value >= 0)
            {
                return value / divisor;
            }

            return -(((-value) + divisor - 1) / divisor);
        }

        void ReduceComposedShadowToLegacyTextureLimit(ComposedFramePackImage& composed)
        {
            constexpr std::uint32_t kLegacyMaxShadowTextureSize = 128U;
            if (composed.image.Empty() ||
                (composed.image.width <= kLegacyMaxShadowTextureSize &&
                    composed.image.height <= kLegacyMaxShadowTextureSize))
            {
                return;
            }

            std::uint32_t shift = 0U;
            std::uint32_t reducedWidth = composed.image.width;
            std::uint32_t reducedHeight = composed.image.height;
            while (reducedWidth > kLegacyMaxShadowTextureSize ||
                reducedHeight > kLegacyMaxShadowTextureSize)
            {
                reducedWidth = std::max(1U, reducedWidth >> 1U);
                reducedHeight = std::max(1U, reducedHeight >> 1U);
                ++shift;
            }

            graphics::ImageData reduced;
            reduced.width = reducedWidth;
            reduced.height = reducedHeight;
            reduced.format = graphics::PixelFormat::Rgba8;
            reduced.pixels.assign(static_cast<std::size_t>(reduced.width) * reduced.height * 4U, 0U);

            for (std::uint32_t y = 0; y < composed.image.height; ++y)
            {
                const auto destY = std::min(reduced.height - 1U, y >> shift);
                for (std::uint32_t x = 0; x < composed.image.width; ++x)
                {
                    const auto srcBase = (static_cast<std::size_t>(y) * composed.image.width + x) * 4U;
                    const auto alpha = composed.image.pixels[srcBase + 3U];
                    if (alpha == 0U)
                    {
                        continue;
                    }

                    const auto destX = std::min(reduced.width - 1U, x >> shift);
                    const auto destBase = (static_cast<std::size_t>(destY) * reduced.width + destX) * 4U;
                    reduced.pixels[destBase + 0U] = 0U;
                    reduced.pixels[destBase + 1U] = 0U;
                    reduced.pixels[destBase + 2U] = 0U;
                    reduced.pixels[destBase + 3U] = std::max(reduced.pixels[destBase + 3U], alpha);
                }
            }

            composed.image = std::move(reduced);
            composed.originX = DivideLegacyShadowOrigin(composed.originX, shift);
            composed.originY = DivideLegacyShadowOrigin(composed.originY, shift);
        }

        struct SpritePackResolveResult
        {
            std::filesystem::path packPath;
            std::filesystem::path indexPath;
            std::wstring cacheName;
            std::wstring extension;
            assets::LegacyAssetFormat format{ assets::LegacyAssetFormat::IndexedSpritePack };
        };

        std::size_t ResolveFramePackFrameCount(
            const std::vector<assets::LegacyFrameSequence>& frameSequences,
            const std::vector<std::pair<std::uint32_t, assets::LegacyIndexedColorMapping>>& bodyDrawOrder,
            const std::uint32_t action,
            const std::uint32_t direction) noexcept
        {
            std::size_t frameCount = 0U;
            for (const auto& layer : bodyDrawOrder)
            {
                const auto* sequence = FindFrameSequence(frameSequences, layer.first, action, direction);
                if (sequence != nullptr)
                {
                    frameCount = std::max(frameCount, sequence->frames.size());
                }
            }
            return frameCount;
        }

        std::optional<ComposedFramePackImage> ComposeFramePackPreviewFromPaths(
            assets::SpriteArchiveReader& spriteReader,
            const std::filesystem::path& spritePackDirectory,
            const std::filesystem::path& spritePackIndex,
            const std::wstring_view spritePackCacheName,
            const std::wstring_view spritePackExtension,
            const assets::LegacyAssetFormat spritePackFormat,
            const std::vector<assets::LegacyFrameSequence>& frameSequences,
            const std::vector<std::pair<std::uint32_t, assets::LegacyIndexedColorMapping>>& bodyDrawOrder,
            const std::uint32_t action,
            const std::uint32_t direction,
            const std::size_t frameIndex,
            std::map<std::uint64_t, graphics::ImageData>& spriteCache)
        {
            struct PlacedImage
            {
                graphics::ImageData image;
                std::int32_t x{ 0 };
                std::int32_t y{ 0 };
            };

            std::vector<PlacedImage> placedImages;
            std::int32_t minX = std::numeric_limits<std::int32_t>::max();
            std::int32_t minY = std::numeric_limits<std::int32_t>::max();
            std::int32_t maxX = std::numeric_limits<std::int32_t>::min();
            std::int32_t maxY = std::numeric_limits<std::int32_t>::min();

            for (const auto& layer : bodyDrawOrder)
            {
                const auto body = layer.first;
                const auto* sequence = FindFrameSequence(frameSequences, body, action, direction);
                if (sequence == nullptr || sequence->frames.empty())
                {
                    continue;
                }

                if (frameIndex >= sequence->frames.size())
                {
                    continue;
                }
                const auto& frame = sequence->frames[frameIndex];
                auto image = ReadIndexedSpriteFromSplitPackFromPaths(
                    spriteReader,
                    spritePackDirectory,
                    spritePackIndex,
                    spritePackCacheName,
                    spritePackExtension,
                    spritePackFormat,
                    frame.spriteId.ValueOf(),
                    layer.second,
                    spriteCache);
                if (!image || image->Empty())
                {
                    continue;
                }

                const auto left = frame.originX;
                const auto top = frame.originY;
                const auto right = left + static_cast<std::int32_t>(image->width);
                const auto bottom = top + static_cast<std::int32_t>(image->height);
                minX = std::min(minX, left);
                minY = std::min(minY, top);
                maxX = std::max(maxX, right);
                maxY = std::max(maxY, bottom);
                placedImages.push_back(PlacedImage{ std::move(*image), left, top });
            }

            if (placedImages.empty() || minX >= maxX || minY >= maxY)
            {
                return std::nullopt;
            }

            graphics::ImageData composed;
            composed.width = static_cast<std::uint32_t>(maxX - minX);
            composed.height = static_cast<std::uint32_t>(maxY - minY);
            composed.format = graphics::PixelFormat::Rgba8;
            composed.pixels.assign(static_cast<std::size_t>(composed.width) * composed.height * 4U, 0U);

            for (const auto& placed : placedImages)
            {
                BlitImage(composed, placed.image, placed.x - minX, placed.y - minY);
            }

            return ComposedFramePackImage{ std::move(composed), minX, minY };
        }

        std::optional<ComposedFramePackImage> ComposeFramePackPreviewWithLayerSpritePacks(
            assets::SpriteArchiveReader& spriteReader,
            const std::vector<assets::LegacyFrameSequence>& frameSequences,
            const std::vector<std::pair<std::uint32_t, assets::LegacyIndexedColorMapping>>& bodyDrawOrder,
            const std::uint32_t action,
            const std::uint32_t direction,
            const std::size_t frameIndex,
            std::map<std::uint64_t, graphics::ImageData>& spriteCache,
            const std::function<std::optional<SpritePackResolveResult>(std::uint32_t body)>& resolveSpritePack)
        {
            struct PlacedImage
            {
                graphics::ImageData image;
                std::int32_t x{ 0 };
                std::int32_t y{ 0 };
            };

            std::vector<PlacedImage> placedImages;
            std::int32_t minX = std::numeric_limits<std::int32_t>::max();
            std::int32_t minY = std::numeric_limits<std::int32_t>::max();
            std::int32_t maxX = std::numeric_limits<std::int32_t>::min();
            std::int32_t maxY = std::numeric_limits<std::int32_t>::min();

            for (const auto& layer : bodyDrawOrder)
            {
                const auto body = layer.first;
                const auto* sequence = FindFrameSequence(frameSequences, body, action, direction);
                if (sequence == nullptr || sequence->frames.empty())
                {
                    continue;
                }

                const auto spritePack = resolveSpritePack(body);
                if (!spritePack)
                {
                    continue;
                }

                if (frameIndex >= sequence->frames.size())
                {
                    continue;
                }
                const auto& frame = sequence->frames[frameIndex];
                auto image = ReadIndexedSpriteFromSplitPackFromPaths(
                    spriteReader,
                    spritePack->packPath,
                    spritePack->indexPath,
                    spritePack->cacheName,
                    spritePack->extension,
                    spritePack->format,
                    frame.spriteId.ValueOf(),
                    layer.second,
                    spriteCache);
                if (!image || image->Empty())
                {
                    continue;
                }

                const auto left = frame.originX;
                const auto top = frame.originY;
                const auto right = left + static_cast<std::int32_t>(image->width);
                const auto bottom = top + static_cast<std::int32_t>(image->height);
                minX = std::min(minX, left);
                minY = std::min(minY, top);
                maxX = std::max(maxX, right);
                maxY = std::max(maxY, bottom);
                placedImages.push_back(PlacedImage{ std::move(*image), left, top });
            }

            if (placedImages.empty() || minX >= maxX || minY >= maxY)
            {
                return std::nullopt;
            }

            graphics::ImageData composed;
            composed.width = static_cast<std::uint32_t>(maxX - minX);
            composed.height = static_cast<std::uint32_t>(maxY - minY);
            composed.format = graphics::PixelFormat::Rgba8;
            composed.pixels.assign(static_cast<std::size_t>(composed.width) * composed.height * 4U, 0U);

            for (const auto& placed : placedImages)
            {
                BlitImage(composed, placed.image, placed.x - minX, placed.y - minY);
            }

            return ComposedFramePackImage{ std::move(composed), minX, minY };
        }

        std::optional<ComposedFramePackImage> ComposeFramePackPreview(
            assets::SpriteArchiveReader& spriteReader,
            const std::filesystem::path& imageRoot,
            const std::wstring_view spritePackName,
            const std::wstring_view spritePackExtension,
            const assets::LegacyAssetFormat spritePackFormat,
            const std::vector<assets::LegacyFrameSequence>& frameSequences,
            const std::vector<std::pair<std::uint32_t, assets::LegacyIndexedColorMapping>>& bodyDrawOrder,
            const std::uint32_t action,
            const std::uint32_t direction,
            const std::size_t frameIndex,
            std::map<std::uint64_t, graphics::ImageData>& spriteCache)
        {
            const auto extensionString = std::wstring(spritePackExtension);
            const auto spritePackDirectory = imageRoot / (std::wstring(spritePackName) + L"." + extensionString);
            const auto spritePackIndex = imageRoot / (std::wstring(spritePackName) + L"." + extensionString + L"i");
            return ComposeFramePackPreviewFromPaths(
                spriteReader,
                spritePackDirectory,
                spritePackIndex,
                std::wstring(spritePackName) + L"." + extensionString,
                spritePackExtension,
                spritePackFormat,
                frameSequences,
                bodyDrawOrder,
                action,
                direction,
                frameIndex,
                spriteCache);
        }

        std::wstring ToWide(const std::string& value)
        {
            return std::wstring(value.begin(), value.end());
        }

        std::string ToNarrowLossy(const std::wstring& value)
        {
            std::string result;
            result.reserve(value.size());
            for (const wchar_t ch : value)
            {
                result.push_back(ch >= 0 && ch <= 0x7F ? static_cast<char>(ch) : '?');
            }
            return result;
        }

