        std::size_t UiEditorListVisibleRows(const ui::UiRect& panel) noexcept
        {
            return std::max<std::size_t>(
                1,
                static_cast<std::size_t>((panel.height - kUiEditorListHeaderHeight - kUiEditorListFooterHeight) / kUiEditorListRowHeight));
        }

        std::size_t ClampUiEditorListOffset(const std::size_t offset, const std::size_t itemCount, const std::size_t visibleRows) noexcept
        {
            if (itemCount <= visibleRows)
            {
                return 0;
            }

            return std::min(offset, itemCount - visibleRows);
        }

        ui::UiRect UiEditorListScrollbarTrack(const ui::UiRect& panel) noexcept
        {
            return ui::UiRect{ panel.x + panel.width - 18, panel.y + kUiEditorListHeaderHeight, 10, panel.height - kUiEditorListHeaderHeight - kUiEditorListFooterHeight };
        }

        ui::UiRect UiEditorListScrollbarThumb(
            const ui::UiRect& track,
            const std::size_t itemCount,
            const std::size_t visibleRows,
            const std::size_t offset) noexcept
        {
            if (itemCount <= visibleRows || track.height <= 0)
            {
                return ui::UiRect{ track.x, track.y, track.width, track.height };
            }

            const auto thumbHeight = std::clamp(
                static_cast<std::int32_t>((static_cast<std::int64_t>(track.height) * static_cast<std::int64_t>(visibleRows)) / static_cast<std::int64_t>(itemCount)),
                24,
                track.height);
            const auto scrollRange = itemCount - visibleRows;
            const auto thumbTravel = std::max(0, track.height - thumbHeight);
            const auto thumbOffset = static_cast<std::int32_t>(
                (static_cast<std::int64_t>(thumbTravel) * static_cast<std::int64_t>(offset)) / static_cast<std::int64_t>(scrollRange));
            return ui::UiRect{ track.x, track.y + thumbOffset, track.width, thumbHeight };
        }

