                ClearPlayerPendingMoves();
                gameSession_.player.queuedMove = false;
                mouseMoveActive_ = false;
                mouseMovePath_.clear();
                if (packetId == protocol::PacketId::GCUntransformOK)
                {
                    gameSession_.player.creatureType = ResolvePlayerCreatureType();
                    ConfigurePlayerAnimation();
                    InvalidateLocalPlayerCreatureVisual();
                }
                ++gameSession_.world.supportPacketCount;
