    std::filesystem::path Application::ResolveFileDefPath(
        const std::wstring_view key,
        const std::wstring_view fallbackRelativePath) const
    {
        if (fileDefCatalog_ && fileDefCatalog_->Succeeded())
        {
            return fileDefCatalog_->Resolve(key, fallbackRelativePath);
        }
        return (phoenix::filesystem::GameDataRoot() / std::filesystem::path(std::wstring(fallbackRelativePath))).lexically_normal();
    }

    std::filesystem::path Application::ResolveExistingFileDefPath(
        const std::wstring_view key,
        const std::wstring_view fallbackRelativePath) const
    {
        const auto resolved = ResolveFileDefPath(key, fallbackRelativePath);
        if (std::filesystem::exists(resolved))
        {
            return resolved;
        }

        const auto fallback = (phoenix::filesystem::GameDataRoot() /
            std::filesystem::path(std::wstring(fallbackRelativePath))).lexically_normal();
        if (fallback != resolved && std::filesystem::exists(fallback))
        {
            return fallback;
        }

        return resolved;
    }

    bool Application::EnsureLegacyUiSpriteCatalogLoaded()
    {
        if (legacyUiSpriteResourceReport_.has_value())
        {
            return legacyUiSpriteResourceReport_->Succeeded();
        }

        ui::LegacyUiSpriteResourceLoader loader;
        legacyUiSpriteResourceReport_ = loader.Load(
            phoenix::filesystem::GameDataRoot(),
            ui::LegacyUiSpriteLoadMode::RuntimeInventory);

        std::uint32_t smokeIndex = 0;
        for (const auto& smoke : legacyUiSpriteResourceReport_->smokeFrames)
        {
            const auto texture = renderer_.UploadTexture(smoke.image);
            if (texture.handle.IsValid())
            {
                gameUiTextures_[GameUiSpriteId(GameUiSpriteGroup::LegacyCatalogSmoke, 0, smokeIndex)] = texture;
                ++smokeIndex;
            }
        }

        if (logger_ != nullptr)
        {
            logger_->Info(
                L"Legacy UI sprite catalog loaded: entries=" + std::to_wstring(legacyUiSpriteResourceReport_->catalogEntries) +
                L" present=" + std::to_wstring(legacyUiSpriteResourceReport_->presentAssets) +
                L" missing=" + std::to_wstring(legacyUiSpriteResourceReport_->missingAssets) +
                L" indexes=" + std::to_wstring(legacyUiSpriteResourceReport_->presentIndexes) +
                L" audited=" + std::to_wstring(legacyUiSpriteResourceReport_->auditedSpritePacks) +
                L" smokeDecoded=" + std::to_wstring(legacyUiSpriteResourceReport_->decodedSmokeFrames) +
                L" smokeUploaded=" + std::to_wstring(smokeIndex));

            std::size_t warningCount = 0;
            for (const auto& warning : legacyUiSpriteResourceReport_->warnings)
            {
                if (warningCount >= 24U)
                {
                    logger_->Info(
                        L"Legacy UI sprite catalog warnings truncated: remaining=" +
                        std::to_wstring(legacyUiSpriteResourceReport_->warnings.size() - warningCount));
                    break;
                }

                logger_->Info(L"Legacy UI sprite catalog warning: " + warning);
                ++warningCount;
            }
        }

        return legacyUiSpriteResourceReport_->Succeeded();
    }

