    bool Application::EnsureEffectFramePacksLoaded()
    {
        std::lock_guard<std::recursive_mutex> catalogLock(runtimeCatalogMutex_);
        if (effectFrameSequences_.has_value() &&
            normalEffectFrameSequences_.has_value() &&
            shadowEffectFrameSequences_.has_value() &&
            screenEffectFrameSequences_.has_value())
        {
            return !effectFrameSequences_->empty() ||
                !normalEffectFrameSequences_->empty() ||
                !shadowEffectFrameSequences_->empty() ||
                !screenEffectFrameSequences_->empty();
        }

        assets::EffectFramePackReader reader;
        (void)EnsureFileDefCatalogLoaded();

        auto effects = reader.ReadEffectFrames(ResolveFileDefPath(L"FILE_EFRAME_ALPHAEFFECT", L"Image\\Effect.efpk"));
        if (effects.value)
        {
            effectFrameSequences_ = std::move(*effects.value);
        }
        else
        {
            effectFrameSequences_ = std::vector<assets::LegacyEffectFrameSequence>{};
            if (logger_ != nullptr)
            {
                logger_->Error(L"effect.efpk load failed.");
            }
        }

        auto normalEffects = reader.ReadEffectFrames(ResolveFileDefPath(L"FILE_EFRAME_NORMALEFFECT", L"Image\\NormalEffect.efpk"));
        if (normalEffects.value)
        {
            normalEffectFrameSequences_ = std::move(*normalEffects.value);
        }
        else
        {
            normalEffectFrameSequences_ = std::vector<assets::LegacyEffectFrameSequence>{};
            if (logger_ != nullptr)
            {
                logger_->Error(L"normaleffect.efpk load failed.");
            }
        }

        auto shadowEffects = reader.ReadEffectFrames(ResolveFileDefPath(L"FILE_EFRAME_SHADOWEFFECT", L"Image\\ShadowEffect.efpk"));
        if (shadowEffects.value)
        {
            shadowEffectFrameSequences_ = std::move(*shadowEffects.value);
        }
        else
        {
            shadowEffectFrameSequences_ = std::vector<assets::LegacyEffectFrameSequence>{};
            if (logger_ != nullptr)
            {
                logger_->Error(L"shadoweffect.efpk load failed.");
            }
        }

        auto screenEffects = reader.ReadEffectFrames(ResolveFileDefPath(L"FILE_EFRAME_SCREENEFFECT", L"Image\\EffectScreen.efpk"));
        if (screenEffects.value)
        {
            screenEffectFrameSequences_ = std::move(*screenEffects.value);
        }
        else
        {
            screenEffectFrameSequences_ = std::vector<assets::LegacyEffectFrameSequence>{};
            if (logger_ != nullptr)
            {
                logger_->Error(L"effectscreen.efpk load failed.");
            }
        }

        if (logger_ != nullptr)
        {
            logger_->Info(
                L"Effect frame packs loaded: alpha=" + std::to_wstring(effectFrameSequences_->size()) +
                L" normal=" + std::to_wstring(normalEffectFrameSequences_->size()) +
                L" shadow=" + std::to_wstring(shadowEffectFrameSequences_->size()) +
                L" screen=" + std::to_wstring(screenEffectFrameSequences_->size()));
        }
        return !effectFrameSequences_->empty() ||
            !normalEffectFrameSequences_->empty() ||
            !shadowEffectFrameSequences_->empty() ||
            !screenEffectFrameSequences_->empty();
    }

