    std::optional<ui::UiRect> Application::LegacyGameMenuReferenceRect()
    {
        const auto key = LegacyGameMenuKey();
        (void)LoadLegacyGameUiSpriteTextures(key, static_cast<std::uint16_t>(kLegacyGameMenuButtons.size() + 8U));
        const auto* main = FindLegacyGameUiSpriteTexture(key, LegacyGameMenuMain);
        if (main == nullptr || main->width == 0U || main->height == 0U)
        {
            return std::nullopt;
        }

        return ui::UiRect{
            640 - (static_cast<std::int32_t>(main->width) / 2),
            480 - (static_cast<std::int32_t>(main->height) / 2),
            static_cast<std::int32_t>(main->width),
            static_cast<std::int32_t>(main->height)
        };
    }

