    ui::UiRect Application::ScaleUiRect(const ui::UiRect rect) const noexcept
    {
        const auto transform = ui::LayoutViewport::BuildTransform(ui::ReferenceCanvas{ 1280, 960 }, ui::ScreenViewport{ display_.width, display_.height });
        return ui::LayoutViewport::ScaleRect(rect, transform);
    }

    ui::FrontendLayout Application::BuildServerSelectLayout() const
    {
        auto layout = ui::FrontendLayoutCatalog::Create(ui::FrontendLayoutScreen::ServerSelect, ui::FrontendLayoutResolution::R1920x1080);
        for (auto& element : layout.elements)
        {
            const auto id = NarrowAscii(element.id.value);
            element.rect = LayoutRect("ServerSelect_1280x960." + id.substr(id.find('.') + 1), element.rect);
        }
        return ui::FrontendLayoutCatalog::ScaleToViewport(layout, ui::ScreenViewport{ display_.width, display_.height });
    }

